-- proc/module.lua - kernel module loading and unloading: the modules.idx
-- index, dependencies, ABI and version checks, trust of module files, and
-- unload with reverse-dependency and device checks.

---@class module
module = {}

-- Version of the module interface; a manifest's abi must equal it.
module.ABI = 1
-- Generated by depmod: name -> path, kind, version, depends, driver data.
module.INDEX = "/usr/lib/modules/modules.idx"

---@class module_entry
---@field name string
---@field path string
---@field kind string "module" or "driver"
---@field mod table the module object returned by the file
---@field version string?
---@field version_n integer
---@field desc string
---@field deps string[] names this module depends on
---@field auto boolean loaded as a dependency
---@field size integer file size in bytes

---@type table<string, module_entry>
local loaded = {}
local index = nil
local indexError = nil

-- Modes are octal digits kept in a decimal number (755 = rwxr-xr-x), as in
-- sec/permission.lua: group or other write makes a module file untrusted.
local function writableByOthers(mode)
    local g = math.floor(mode / 10) % 10
    local o = mode % 10
    return g & 2 ~= 0 or o & 2 ~= 0
end

local function isPath(s)
    return s:find("/", 1, true) ~= nil
end

local function copyList(t)
    local out = {}
    for i, v in ipairs(t) do out[i] = v end
    return out
end

-- a dependency as { name, min version_n or nil }
local function depList(depends)
    local out = {}
    for i, d in ipairs(depends or {}) do
        if type(d) == "string" then
            out[i] = { d, nil }
        else
            out[i] = { d[1], d[2] }
        end
    end
    return out
end

local function checkDepends(depends)
    if depends == nil then return true end
    if type(depends) ~= "table" then return false end
    for _, d in ipairs(depends) do
        if type(d) == "string" then
            -- plain name
        elseif type(d) == "table" and type(d[1]) == "string"
            and (d[2] == nil or type(d[2]) == "number") then
            -- { name, min version_n }
        else
            return false
        end
    end
    return true
end

------------------------------------------------------------
-- index
------------------------------------------------------------

local function emptyIndex()
    return { version = 2, abi = module.ABI, modules = {} }
end

local function readIndex()
    local f, err = loadfile(module.INDEX, "bt", {})
    if not f then return emptyIndex(), err or "cannot load index" end
    local ok, data = xpcall(f, debug.traceback)
    if not ok then return emptyIndex(), data end
    if type(data) ~= "table" or type(data.modules) ~= "table" then
        return emptyIndex(), "invalid index"
    end
    if data.abi ~= nil and data.abi ~= module.ABI then
        printk("module: index built for ABI " .. tostring(data.abi)
            .. ", kernel has " .. module.ABI, "warning")
    end
    return data
end

-- The cached index. A missing or broken index is an empty one, with a warning.
---@return table index
---@return string|nil err
function module.index()
    if index == nil then
        index, indexError = readIndex()
        if indexError then
            printk("module: " .. module.INDEX .. ": " .. tostring(indexError), "warning")
        end
    end
    return index, indexError
end

function module.reindex()
    index = nil
    return module.index()
end

-- A name is looked up in the index; anything with "/" is a path.
---@return string|nil path
---@return string|nil err
function module.resolve(nameOrPath)
    if type(nameOrPath) ~= "string" then return nil, "Invalid name" end
    if isPath(nameOrPath) then return vfs.resolve(nameOrPath) end
    local ie = module.index().modules[nameOrPath]
    if not ie then return nil, nameOrPath .. ": not found" end
    return ie.path
end

------------------------------------------------------------
-- evaluating a module file
------------------------------------------------------------

-- Trust: owned by root and not group or other writable. A vnode without
-- metadata counts as trusted.
local function metaTrusted(path)
    local attr = vfs.attributes(path)
    if not attr then return true end
    if attr.uid ~= nil and attr.uid ~= 0 then return false end
    if math.type(attr.mode) == "integer" and writableByOthers(attr.mode) then
        return false
    end
    return true
end

local function trusted(path)
    local dir = path:match("^(.*)/[^/]*$")
    if dir == nil or dir == "" then dir = "/" end
    return metaTrusted(path) and metaTrusted(dir)
end

-- Evaluates a module file without running its load(). Checks trust, shape,
-- driver rules and ABI. Returns the module object and what the file says
-- about itself, or nil and an error.
---@return table|nil mod
---@return table|string info or error
local function evalModule(path)
    if not trusted(path) then
        printk("module: untrusted module file " .. path, "err")
        return nil, "untrusted module file"
    end
    local f, err = loadfile(path, "bt", createModuleEnv())
    if not f then return nil, err or "Unknown Error" end
    local s, mod = xpcall(f, debug.traceback)
    if not s then return nil, mod end
    if type(mod) ~= "table" or type(mod.load) ~= "function"
        or type(mod.unload) ~= "function" or type(mod.module) ~= "table"
        or type(mod.manifest) ~= "table" then
        return nil, "Invalid or not a module"
    end

    local man = mod.manifest
    if type(man.name) ~= "string" or type(man.desc) ~= "string"
        or type(man.version_n) ~= "number"
        or (man.version ~= nil and type(man.version) ~= "string")
        or not checkDepends(man.depends) then
        return nil, "Invalid module manifest"
    end

    local stem = path:match("([^/]+)$")
    local isDriverFile = stem:match("%.drv%.lua$") ~= nil
    if isDriverFile and type(mod.driver) ~= "table" then
        return nil, man.name .. ": driver file must define a driver table"
    end
    if not isDriverFile and mod.driver ~= nil then
        return nil, man.name .. ": driver table in a non-.drv.lua file"
    end
    if isDriverFile and man.name ~= (stem:gsub("%.drv%.lua$", "")) then
        return nil, man.name .. ": driver name must match file name"
    end

    if man.abi == nil then
        printk("module: " .. man.name .. ": no abi in manifest", "warning")
    elseif man.abi ~= module.ABI then
        return nil, man.name .. ": ABI " .. tostring(man.abi)
            .. " required, kernel has " .. tostring(module.ABI)
    end

    local attr = vfs.attributes(path)
    return mod, {
        name = man.name,
        path = path,
        kind = isDriverFile and "driver" or "module",
        version = man.version,
        version_n = man.version_n,
        desc = man.desc,
        depends = depList(man.depends),
        size = attr and attr.size or 0,
    }
end

------------------------------------------------------------
-- loading
------------------------------------------------------------

-- ctx.loading marks modules being resolved (cycle detection); ctx.created
-- lists those registered by this load, undone if it fails.
local function newContext()
    return { loading = {}, created = {} }
end

local function ancestorsWith(ancestors, name)
    local out = copyList(ancestors)
    out[#out + 1] = name
    return out
end

local function register(ctx, name, info, mod, auto)
    local deps = {}
    for i, d in ipairs(info.depends) do deps[i] = d[1] end
    loaded[name] = {
        name = name,
        path = info.path,
        kind = info.kind,
        mod = mod,
        version = info.version,
        version_n = info.version_n,
        desc = info.desc,
        deps = deps,
        auto = auto,
        size = info.size,
    }
    ctx.created[#ctx.created + 1] = name
end

-- Undoes what a failed load registered, newest first.
local function rollback(ctx)
    for i = #ctx.created, 1, -1 do
        local name = ctx.created[i]
        local entry = loaded[name]
        loaded[name] = nil
        local s, err = xpcall(entry.mod.unload, debug.traceback)
        if not s then
            printk("module: unload failed while rolling back '" .. name .. "': " .. tostring(err), "err")
            panic("not syncing", "module: unload of '" .. name .. "' failed")
        end
    end
    ctx.created = {}
end

local loadByName

-- Runs the dependencies of an evaluated module, then its load(), and
-- registers it.
local function instantiate(ctx, mod, info, opts, auto, ancestors, minVersion)
    local name = info.name
    if minVersion and info.version_n < minVersion then
        return nil, name .. ": version " .. minVersion .. " required"
    end
    ctx.loading[name] = true
    local chain = ancestorsWith(ancestors, name)
    for _, dep in ipairs(info.depends) do
        local dname, dmin = dep[1], dep[2]
        if opts.noDeps then
            local e = loaded[dname]
            if not e then return nil, dname .. ": not loaded" end
            if dmin and e.version_n < dmin then
                return nil, dname .. ": version " .. dmin .. " required"
            end
        else
            local dm, err = loadByName(ctx, dname, chain, dmin, true, opts)
            if not dm then return nil, err end
        end
    end
    local s, err = xpcall(mod.load, debug.traceback)
    if not s then return nil, err end
    register(ctx, name, info, mod, auto)
    ctx.loading[name] = nil
    return mod
end

loadByName = function(ctx, name, ancestors, minVersion, auto, opts)
    local e = loaded[name]
    if e then
        if minVersion and e.version_n < minVersion then
            return nil, name .. ": version " .. minVersion .. " required"
        end
        return e.mod
    end
    if ctx.loading[name] then
        return nil, "circular dependency: " .. table.concat(ancestorsWith(ancestors, name), " -> ")
    end
    local ie = module.index().modules[name]
    if not ie then return nil, name .. ": not found" end
    local mod, info = evalModule(ie.path)
    if not mod then return nil, info end
    if info.name ~= name then
        return nil, name .. ": index entry does not match " .. ie.path
    end
    return instantiate(ctx, mod, info, opts, auto, ancestors, minVersion)
end

------------------------------------------------------------
-- dry runs
------------------------------------------------------------

local planName

-- Appends to `order` the modules a load of these dependencies would register.
-- Returns an error string, or nil.
local function planDepends(depends, ancestors, opts, order, seen)
    for _, dep in ipairs(depends) do
        local dname, dmin = dep[1], dep[2]
        local err
        if opts.noDeps then
            local e = loaded[dname]
            if not e then
                err = dname .. ": not loaded"
            elseif dmin and e.version_n < dmin then
                err = dname .. ": version " .. dmin .. " required"
            end
        else
            err = planName(dname, ancestors, dmin, opts, order, seen)
        end
        if err then return err end
    end
    return nil
end

planName = function(name, ancestors, minVersion, opts, order, seen)
    local e = loaded[name]
    if e then
        if minVersion and e.version_n < minVersion then
            return name .. ": version " .. minVersion .. " required"
        end
        return nil
    end
    if seen[name] then return nil end
    for _, a in ipairs(ancestors) do
        if a == name then
            return "circular dependency: " .. table.concat(ancestorsWith(ancestors, name), " -> ")
        end
    end
    local ie = module.index().modules[name]
    if not ie then return name .. ": not found" end
    if minVersion and ie.version_n < minVersion then
        return name .. ": version " .. minVersion .. " required"
    end
    local err = planDepends(depList(ie.depends), ancestorsWith(ancestors, name), opts, order, seen)
    if err then return err end
    order[#order + 1] = name
    seen[name] = true
    return nil
end

-- The order a load would run in (dependencies first, target last), loading nothing.
local function planLoad(nameOrPath, opts)
    local order, seen = {}, {}
    if isPath(nameOrPath) then
        local real = vfs.resolve(nameOrPath)
        if not real then return nil, "Invalid path" end
        local mod, info = evalModule(real)
        if not mod then return nil, info end
        local e = loaded[info.name]
        if e then
            if e.path ~= real then return nil, info.name .. ": already loaded from " .. e.path end
            return order
        end
        local err = planDepends(info.depends, { info.name }, opts, order, seen)
        if err then return nil, err end
        order[#order + 1] = info.name
        return order
    end
    local err = planName(nameOrPath, {}, nil, opts, order, seen)
    if err then return nil, err end
    return order
end

------------------------------------------------------------
-- public load
------------------------------------------------------------

-- Loads a module by index name or by file path. Already loaded by name
-- returns the loaded module. Options: noDeps (dependencies must already
-- be loaded), dryRun (return the load order, load nothing), auto (marks the
-- module as loaded for another one).
---@param nameOrPath string
---@param privileged? boolean
---@param opts? { noDeps?: boolean, dryRun?: boolean, auto?: boolean }
---@return table|string[]|nil mod, string|nil err
function module.load(nameOrPath, privileged, opts)
    if process.current > 0 and not privileged then
        return nil, "Permission Denied"
    end
    if type(nameOrPath) ~= "string" then return nil, "Invalid name" end
    opts = opts or {}
    if opts.dryRun then return planLoad(nameOrPath, opts) end

    local ctx = newContext()
    local mod, err
    if isPath(nameOrPath) then
        local real = vfs.resolve(nameOrPath)
        if not real then return nil, "Invalid path" end
        local m, info = evalModule(real)
        if not m then return nil, info end
        local e = loaded[info.name]
        if e then
            if e.path ~= real then
                return nil, info.name .. ": already loaded from " .. e.path
            end
            return e.mod
        end
        mod, err = instantiate(ctx, m, info, opts, opts.auto == true, {}, nil)
    else
        local e = loaded[nameOrPath]
        if e then return e.mod end
        mod, err = loadByName(ctx, nameOrPath, {}, nil, opts.auto == true, opts)
    end
    if not mod then
        rollback(ctx)
        return nil, err
    end
    return mod
end

------------------------------------------------------------
-- unload
------------------------------------------------------------

local function boundCount(name)
    if devmgr == nil then return 0 end
    return devmgr.boundCount(name)
end

-- Loaded modules that depend on `name`, leaving out `removed`; sorted.
local function usersOf(name, removed)
    local users = {}
    for n, e in pairs(loaded) do
        if not removed[n] then
            for _, d in ipairs(e.deps) do
                if d == name then
                    users[#users + 1] = n
                    break
                end
            end
        end
    end
    table.sort(users)
    return users
end

-- The order an unload would run in, checked as a whole before anything
-- is unloaded. Returns the list, or nil and the refusal.
local function planUnload(name, opts)
    local order, removed = {}, {}

    local function take(n)
        local users = usersOf(n, removed)
        if users[1] then return nil, "in use by " .. users[1] end
        if loaded[n].kind == "driver" and not opts.force and boundCount(n) > 0 then
            return nil, "in use by device"
        end
        removed[n] = true
        order[#order + 1] = n
        return true
    end

    local done, err = take(name)
    if not done then return nil, err end

    if opts.recursive then
        -- auto-loaded dependencies that nothing else uses, last one first
        local function prune(entry)
            for i = #entry.deps, 1, -1 do
                local dn = entry.deps[i]
                local de = loaded[dn]
                if de and de.auto and not removed[dn] and #usersOf(dn, removed) == 0 then
                    local ok, e2 = take(dn)
                    if not ok then return nil, e2 end
                    ok, e2 = prune(de)
                    if not ok then return nil, e2 end
                end
            end
            return true
        end
        done, err = prune(loaded[name])
        if not done then return nil, err end
    end
    return order
end

local function unloadOne(name)
    local e = loaded[name]
    if e.kind == "driver" and boundCount(name) > 0 then
        devmgr.teardownDriver(name, "unload")
    end
    loaded[name] = nil
    local s, err = xpcall(e.mod.unload, debug.traceback)
    if not s then
        printk("module: unload of '" .. name .. "' raised: " .. tostring(err), "err")
        panic("not syncing", "module: unload of '" .. name .. "' failed")
    end
end

-- Unloads a module. Refused while another loaded module uses it, and, for a
-- driver with bound devices, unless `force` (then its devices are torn down).
-- Options: force, recursive (also unload auto-loaded dependencies that are no
-- longer used), dryRun (return the order, unload nothing).
---@param name string
---@param privileged? boolean
---@param opts? { force?: boolean, recursive?: boolean, dryRun?: boolean }
---@return true|string[]|nil ok, string|nil err
function module.unload(name, privileged, opts)
    if process.current > 0 and not privileged then
        return nil, "Permission Denied"
    end
    if type(name) ~= "string" then return nil, "Invalid name" end
    opts = opts or {}
    if not loaded[name] then return nil, "Unknown module" end
    local order, err = planUnload(name, opts)
    if not order then return nil, err end
    if opts.dryRun then return order end
    for _, n in ipairs(order) do unloadOne(n) end
    return true
end

------------------------------------------------------------
-- queries
------------------------------------------------------------

---@return table|nil
function module.require(name)
    local e = loaded[name]
    return e and e.mod.module or nil
end

---@return table|nil mod
function module.get(name)
    local e = loaded[name]
    return e and e.mod or nil
end

function module.exists(name)
    return loaded[name] ~= nil
end

-- A loaded module's record, without the module object.
---@return table|nil
function module.entry(name)
    local e = loaded[name]
    if not e then return nil end
    return {
        name = e.name,
        path = e.path,
        kind = e.kind,
        mod = e.mod,
        version = e.version,
        version_n = e.version_n,
        desc = e.desc,
        deps = copyList(e.deps),
        usedBy = usersOf(name, {}),
        auto = e.auto,
        size = e.size,
    }
end

-- Loaded modules and the index entries not loaded, sorted by name.
---@return table[]
function module.list()
    local out = {}
    for name, e in pairs(loaded) do
        out[#out + 1] = {
            name = name,
            kind = e.kind,
            version = e.version,
            desc = e.desc,
            path = e.path,
            size = e.size,
            usedBy = usersOf(name, {}),
            state = "loaded",
        }
    end
    for name, ie in pairs(module.index().modules) do
        if not loaded[name] then
            out[#out + 1] = {
                name = name,
                kind = ie.kind,
                version = ie.version,
                desc = ie.desc,
                path = ie.path,
                size = ie.size or 0,
                usedBy = {},
                state = "available",
            }
        end
    end
    table.sort(out, function(a, b) return a.name < b.name end)
    return out
end

-- Loads the names or paths listed in /etc/modules.lua, in order.
function module.autoload()
    if process.current > 0 then
        return nil, "Permission Denied"
    end

    local f, err = loadfile("/etc/modules.lua", "bt", util.createEnv())
    if not f then
        printk("module: autoload: " .. (err or "no /etc/modules.lua found"), "warning")
        return
    end

    local s, list = xpcall(f, debug.traceback)
    if not s or type(list) ~= "table" then
        printk("module: autoload: invalid format /etc/modules.lua", "err")
        return
    end

    for _, nameOrPath in ipairs(list) do
        local m, e = module.load(nameOrPath)
        if not m then
            printk("module: autoload: failed to load '" .. tostring(nameOrPath) .. "': " .. tostring(e), "err")
        end
    end
end
